insert into public.chapters (chapter, title, scenarios) values (4, 'Managing in a Global Environment', '{}'::jsonb) on conflict (chapter) do update set title = excluded.title, scenarios = excluded.scenarios;
insert into public.questions (id, chapter, num, scenario, question, options, answer, marked, note) values
('c4-q01', 4, 1, null, 'What did the effect of a volcanic eruption in Iceland on the production of Nissans in a plant in Japan illustrate?', '["how much organizations depend on their banks", "how much organizations depend on their external environment", "how much organizations depend on corporate culture", "how much organizations depend on a strong brand image"]'::jsonb, 'B', 'B', null),
('c4-q02', 4, 2, null, 'Which components of the external environment of the BMW plant in Spartanburg, South Carolina were disrupted by the volcanic eruption in Eyjafjallajökull, Iceland?', '["the demographic and global components", "the political and legal components", "the economic and global components", "the sociocultural and demographic components"]'::jsonb, 'C', 'C', null),
('c4-q03', 4, 3, null, 'Which one of the following is not involved with the demographic component of an organization''s external environment?', '["values", "gender", "race", "income"]'::jsonb, 'A', 'A', null),
('c4-q04', 4, 4, null, 'Court rulings allowing gay marriage are an example of a change in which components of an organization''s external environment?', '["political/legal and technological", "economic and demographic", "sociocultural and global", "sociocultural and political/legal"]'::jsonb, 'D', 'D', null),
('c4-q05', 4, 5, null, 'Which one of the following has been identified as a significant risk to business leaders in the next decade?', '["stagnation in technology", "income disparity", "declining birth rates", "political instability"]'::jsonb, 'B', 'B', null),
('c4-q06', 4, 6, null, 'The use of peer-to-peer services such as Uber is an example of this type of economy.', '["capitalistic", "socialistic", "sharing", "unplanned"]'::jsonb, 'C', 'C', null),
('c4-q07', 4, 7, null, 'Which one of the following views of management would agree with the statement that managers should not be held accountable for changing global economic conditions?', '["the geocentric view", "the new-world order view", "the demographic view", "the symbolic view"]'::jsonb, 'D', null, 'Not marked on the sheet. Symbolic view: much of an organization''s success or failure is due to external forces outside managers'' control.'),
('c4-q08', 4, 8, null, 'Which view of management describes a situation in which managers are directly responsible for a company''s success or failure?', '["the structural view of management", "the symbolic view of management", "the omnipotent view of management", "the realistic view of management"]'::jsonb, 'C', null, 'Not marked on the sheet. Omnipotent view: managers are directly responsible for an organization''s success or failure.'),
('c4-q09', 4, 9, null, 'Which kind of company would be less likely to fire its CEO for poor performance?', '["a company with a symbolic view of management", "a company with a realistic view of management", "a company with an external view of management", "a company with an omnipotent view of management"]'::jsonb, 'A', null, 'Not marked on the sheet. In the symbolic view, poor results are blamed on external forces, not on the CEO.'),
('c4-q10', 4, 10, null, 'Experts predict that these two countries will be larger than the developed countries of the world by the year 2050.', '["Mexico and China", "India and China", "China and South Africa", "India and Mexico"]'::jsonb, 'B', 'B', 'On the sheet B is circled and C is partly marked. India and China → B.'),
('c4-q11', 4, 11, null, 'Which one of the following identifies the best illustration of the phrase "demographics is destiny?"', '["India is experiencing explosive growth partly because its population is growing rapidly.", "India is experiencing poverty because its population is growing rapidly.", "The United States is experiencing slow growth partly because its population is growing rapidly.", "The United States is experiencing healthy growth partly because its population is not growing and people are saving their resources."]'::jsonb, 'A', null, 'Not marked on the sheet. "Demographics is destiny": population size/characteristics drive economic outcomes – e.g. India''s growth partly driven by a rapidly growing population.'),
('c4-q12', 4, 12, null, 'Which demographic do managers pay closest attention to with respect to large-scale trends in the business world?', '["age", "sex", "employment status", "geographic location"]'::jsonb, 'A', null, 'Not marked on the sheet. The textbook focuses on age cohorts (Baby Boomers, Gen X, Gen Y, Gen Z).'),
('c4-q13', 4, 13, null, 'How are Gen Z workers likely to be different from previous generations?', '["They require products that are Internet-enabled.", "They require products that are completely generic and not at all customized to the individual.", "They require products that are serious and meaningful rather than frivolous and fun.", "They require products that are of much higher quality than those required by individuals in previous generations."]'::jsonb, 'A', null, 'Not marked on the sheet. Gen Z are digital natives who grew up with the Internet.'),
('c4-q14', 4, 14, null, 'Which generation is predicted to be the most diverse and multicultural of any generation in the United States?', '["Baby Boomers", "Generation X", "Generation Y", "Generation Z"]'::jsonb, 'D', 'D', null),
('c4-q15', 4, 15, 'TJ Soft', 'Theodore and Janice have formed TJ Soft, an entrepreneurial venture to develop games and other kinds of software for consumers. Theodore feels that success depends on the decisions that he and Janice make in the near future with respect to personnel. If they hire the "right" people, Theodore thinks, the company will be successful. Which view of management does Theodore espouse?', '["the symbolic view of management, because success rides on the decisions of the managers", "the symbolic view of management, because success rides on external factors—whom Theodore and Janice hire from the outside world", "the omnipotent view of management, because success rides on the skills of the workers", "the omnipotent view of management, because success rides on the decisions of the managers"]'::jsonb, 'D', 'D', null),
('c4-q16', 4, 16, 'TJ Soft', 'Theodore and Janice have formed TJ Soft, an entrepreneurial venture to develop games and other kinds of software for consumers. Janice loves the company but feels that the economy is too slow to expect any kind of overwhelming success at this point in time. For now, Janice just wants the company to survive. In a few years the company perhaps can look forward to true success. Which view of management does Janice espouse?', '["the omnipotent view of management, because success rides on external factors such as the economy", "the symbolic view of management, because success rides on external factors such as the economy", "the symbolic view of management, because success rides on internal factors such as the judgment of Theodore and Janice", "the omnipotent view of management, because success rides on internal factors such as the judgment of Theodore and Janice"]'::jsonb, 'B', 'B', null),
('c4-q17', 4, 17, 'TJ Soft', 'Theodore and Janice have formed TJ Soft, an entrepreneurial venture to develop games and other kinds of software for consumers. Theodore has just gotten wind from a highly reliable source that games involving animals and ecosystems are likely to be extremely "hot" in the coming year. Theodore is excited because TJ Soft has two games in development that fit the animal/eco niche perfectly. Which component of the external environment will affect TJ Soft the most in this situation?', '["the demographic component", "the political component", "the sociocultural component", "the global component"]'::jsonb, 'C', null, 'Not marked on the sheet. Changing tastes and trends in what people value = sociocultural component.'),
('c4-q18', 4, 18, 'TJ Soft', 'Theodore and Janice have formed TJ Soft, an entrepreneurial venture to develop games and other kinds of software for consumers. Theodore has just gotten wind from a highly reliable source that Congress is likely to take action in the coming year to ban violent games. TJ Soft has several games that could be considered violent. Which component of the external environment will affect TJ Soft the most in this situation?', '["the political/legal component", "the demographic component", "the technological component", "the economic component"]'::jsonb, 'A', null, 'Not marked on the sheet. Congress / laws = political/legal component.'),
('c4-q19', 4, 19, null, 'Why were the Baby Boomers so much more influential than other generations with respect to changing American tastes and culture?', '["The Baby Boomers came after World War II when lifestyles were really changing.", "The Baby Boomers were a much more coherent group than other generations.", "The Baby Boomers were a much larger group than other generations.", "The Baby Boomers were a much more free-spirited group than other generations."]'::jsonb, 'C', null, 'Not marked on the sheet. Their sheer size made them the dominant force.'),
('c4-q20', 4, 20, 'TJ Soft', 'Theodore and Janice have formed TJ Soft, an entrepreneurial venture to develop games and other kinds of software for consumers. Theodore has just gotten wind that engineers have developed a new computer system that works like the devices shown in the Steven Spielberg movie Minority Report in which users can control a sophisticated computer using their hands in midair. Janice sees this development as highly important to new games for TJ Soft. Which component of the external environment will affect TJ Soft the most in this situation?', '["the global component", "the sociocultural component", "the economic component", "the technological component"]'::jsonb, 'D', null, 'Not marked on the sheet. New computer system = technological component.'),
('c4-q21', 4, 21, 'TJ Soft', 'Theodore and Janice have formed TJ Soft, an entrepreneurial venture to develop games and other kinds of software for consumers. Theodore has just read an article that describes the explosion of computer games among young people in India using cell phones and simple computers. This generation in India has well over 300 million people in it, and if TJ Soft can capture just a tiny portion of that market it will be highly successful. Which component of the external environment will affect TJ Soft the most in this situation?', '["the technological component", "the demographic component", "the political component", "the legal component"]'::jsonb, 'B', null, 'Not marked on the sheet. Size and age of a population group (a generation of 300 million) = demographic component.'),
('c4-q22', 4, 22, 'TJ Soft', 'Theodore and Janice have formed TJ Soft, an entrepreneurial venture to develop games and other kinds of software for consumers. Theodore has just read an article that says that the low interest rates that currently prevail are likely to end in the coming months. Theodore thinks that TJ Soft may need to apply for a loan now to avoid high costs later. Which component of the external environment will affect TJ Soft the most in this situation?', '["the global component", "the sociocultural component", "the economic component", "the technological component"]'::jsonb, 'C', null, 'Not marked on the sheet. Interest rates = economic component.'),
('c4-q23', 4, 23, null, 'Apple, which lives and breathes new product development, emphasizes which dimension of organizational culture?', '["member identity", "innovation", "people focus", "conflict tolerance"]'::jsonb, 'B', null, 'Not marked on the sheet.'),
('c4-q24', 4, 24, null, 'All of the following show why corporate rituals can be valuable in a corporate culture EXCEPT ________.', '["rituals help initiate new employees into the culture", "rituals reinforce corporate values", "rituals symbolize key ideas that are important in the culture", "rituals intimidate and silence critics of the corporate culture"]'::jsonb, 'D', null, 'Not marked on the sheet.'),
('c4-q25', 4, 25, null, 'Art Fry of 3M developed a weak glue that was not permanent when applied to surfaces, but he had no application for it–until he saw the choir director using small pieces of paper to mark pages in the hymnal and watched as those papers fell out. After applying his glue to small squares of paper, he solved the choir director''s problem and created Post-It Notes® What is the implicit message in a story like the tale of the Post-it® note and Art Fry?', '["Your problems are not as difficult as the problems that Art Fry faced so you shouldn''t complain.", "You can solve your problems in novel and creative ways just like Art Fry.", "Your problems are much harder than the problems that Art Fry faced, but the tools you have to solve them are much better.", "Your problems are not like the problems that Art Fry faced so you can''t solve them in the same way."]'::jsonb, 'B', null, 'Not marked on the sheet.'),
('c4-q26', 4, 26, null, 'How is a corporate ritual different from a corporate story or legend?', '["A ritual does not attempt to teach a specific lesson while a story or legend does.", "A story or legend does not attempt to teach a specific lesson while a ritual does.", "A ritual is not to be taken seriously while a story or legend is.", "A story or legend is not to be taken seriously while a ritual is."]'::jsonb, 'A', null, 'Not marked on the sheet. Stories teach a lesson (narratives of significant events); rituals are repetitive activities that express and reinforce values.'),
('c4-q27', 4, 27, null, 'Organizational culture affects managers in two main ways: 1) its effect on what employees do and how they behave and 2) ________.', '["the benefits and rewards established by the founder", "its effect on organizational structure", "its effect on what managers do", "the communication pattern between organizational members"]'::jsonb, 'C', null, 'Not marked on the sheet.'),
('c4-q28', 4, 28, null, 'When rating how deeply held values are within an organization, culture is ranked from ________ to ________.', '["strong; weak", "long-term; short-term", "deep; shallow", "static; dynamic"]'::jsonb, 'A', null, 'Not marked on the sheet.'),
('c4-q29', 4, 29, null, 'Which one of the following most accurately reflects the difference between strong cultures and weak cultures?', '["Strong cultures tend to encourage employee innovation, while weak cultures do not.", "Weak cultures are found in most successful organizations, whereas strong cultures are relatively rare.", "Strong cultures have less of an influence on employee behavior than do weak cultures.", "Company values are more deeply held and widely shared in strong cultures than in weak cultures."]'::jsonb, 'D', null, 'Not marked on the sheet. Strong cultures = key values deeply held and widely shared.'),
('c4-q30', 4, 30, null, 'What determines whether an organization has a strong culture or a weak culture?', '["how much employees are compensated for their efforts and whether they think their compensation is fair", "how much employees accept the organization''s key values and are committed to those values", "whether or not employees feel that the organization is ethical", "how fairly employees feel that they are being treated"]'::jsonb, 'B', 'B', null),
('c4-q31', 4, 31, null, 'Which kind of culture most affects the way managers plan?', '["A weak organizational culture gives managers the freedom to make their own decisions.", "A strong organizational culture gives managers the freedom to make their own decisions independent of organizational values.", "A strong organizational culture helps guide the way managers plan.", "A weak organizational culture helps guide the way managers plan."]'::jsonb, 'C', null, 'Not marked on the sheet.'),
('c4-q32', 4, 32, null, 'Which one of the following statements about organizational culture is correct?', '["An organization with a weak culture would need fewer written rules and regulations to conduct business than a strong culture.", "An organization with a strong culture would need more written rules and regulations to conduct business than a weak culture.", "An organization with a strong culture would need fewer written rules and regulations to conduct business than a weak culture.", "Both weak and strong organizational cultures need as many written rules and regulations to conduct business as possible."]'::jsonb, 'C', null, 'Not marked on the sheet. A strong culture substitutes for formal rules.'),
('c4-q33', 4, 33, null, 'Which kind of organizational culture do the following values describe?
insert into public.open_questions (id, chapter, num, question, model_answer) values
('c4-o1', 4, 1, 'In a short essay, describe the difference between a strong and a weak organizational culture and how both affect organizational behavior.', 'A strong culture is one in which the key values are intensely held and widely shared by employees; a weak culture is one where values are not clearly defined, held by only a few people, or not deeply committed to.
